/// Stage filter coefficients selected by phase and apodization.
#[derive(Debug, Clone, Copy, PartialEq)]
pub enum HalfBandTaps {
    /// Symmetric half-band prototype stored as unique positive odd taps.
    Symmetric(&'static [f64]),
    /// General full-length FIR prototype stored as all taps.
    General(&'static [f64]),
}

/// Linear-phase half-band odd taps of 2x stage `stage` (interpolation stage index, or the decimator's
/// stage counted back from its output). Stages beyond the table reuse the last (most relaxed) design.
pub fn get_halfband_odd_taps(stage: usize) -> &'static [f64] {
    match stage {
        0 => &HALFBAND_STAGE0_ODD_TAPS,
        1 => &HALFBAND_STAGE1_ODD_TAPS,
        2 => &HALFBAND_STAGE2_ODD_TAPS,
        3 => &HALFBAND_STAGE3_ODD_TAPS,
        4 => &HALFBAND_STAGE4_ODD_TAPS,
        5 => &HALFBAND_STAGE5_ODD_TAPS,
        6 => &HALFBAND_STAGE6_ODD_TAPS,
        7 => &HALFBAND_STAGE7_ODD_TAPS,
        _ => &HALFBAND_STAGE8_ODD_TAPS,
    }
}

/// Minimum-phase half-band taps of 2x stage `stage` (same stage rule as `get_halfband_odd_taps`).
pub fn get_halfband_minimum_taps(stage: usize) -> &'static [f64] {
    match stage {
        0 => &HALFBAND_STAGE0_MINIMUM_TAPS,
        1 => &HALFBAND_STAGE1_MINIMUM_TAPS,
        2 => &HALFBAND_STAGE2_MINIMUM_TAPS,
        3 => &HALFBAND_STAGE3_MINIMUM_TAPS,
        4 => &HALFBAND_STAGE4_MINIMUM_TAPS,
        5 => &HALFBAND_STAGE5_MINIMUM_TAPS,
        6 => &HALFBAND_STAGE6_MINIMUM_TAPS,
        7 => &HALFBAND_STAGE7_MINIMUM_TAPS,
        _ => &HALFBAND_STAGE8_MINIMUM_TAPS,
    }
}

/// Returns the filter of 2x interpolation stage `stage`. Apodization only affects stage 0.
pub fn get_interpolation_stage_filter(
    stage: usize,
    phase: FilterPhase,
    apodization: Apodization,
) -> HalfBandTaps {
    if stage == 0 {
        let apodizing: Option<&'static [f64]> = match (apodization, phase) {
            (Apodization::Off, _) => None,
            (Apodization::PassEdge18000, FilterPhase::Linear) => Some(&APODIZING_18000_LINEAR_TAPS),
            (Apodization::PassEdge18000, FilterPhase::Minimum) => {
                Some(&APODIZING_18000_MINIMUM_TAPS)
            }
            (Apodization::PassEdge18500, FilterPhase::Linear) => Some(&APODIZING_18500_LINEAR_TAPS),
            (Apodization::PassEdge18500, FilterPhase::Minimum) => {
                Some(&APODIZING_18500_MINIMUM_TAPS)
            }
            (Apodization::PassEdge19000, FilterPhase::Linear) => Some(&APODIZING_19000_LINEAR_TAPS),
            (Apodization::PassEdge19000, FilterPhase::Minimum) => {
                Some(&APODIZING_19000_MINIMUM_TAPS)
            }
            (Apodization::PassEdge20000, FilterPhase::Linear) => Some(&APODIZING_20000_LINEAR_TAPS),
            (Apodization::PassEdge20000, FilterPhase::Minimum) => {
                Some(&APODIZING_20000_MINIMUM_TAPS)
            }
        };
        if let Some(taps) = apodizing {
            return HalfBandTaps::General(taps);
        }
    }
    match phase {
        FilterPhase::Linear => HalfBandTaps::Symmetric(get_halfband_odd_taps(stage)),
        FilterPhase::Minimum => HalfBandTaps::General(get_halfband_minimum_taps(stage)),
    }
}

/// SRC prototype cutoff, as a fraction of the lower of the two rates (Design.md §4.2, `design_src.py`).
pub const SRC_CUTOFF: f64 = 0.5;
/// SRC passband edge (20 kHz at 44.1 kHz), as a fraction of the lower rate.
pub const SRC_PASS_EDGE: f64 = 0.45351473922902497;
/// SRC stopband edge (24.1 kHz at 44.1 kHz), as a fraction of the lower rate.
pub const SRC_STOP_EDGE: f64 = 0.546485260770975;
/// Kaiser window beta of the SRC prototype (140 dB design attenuation).
pub const SRC_KAISER_BETA: f64 = 14.469260000000002;
/// SRC taps per output sample when no downsampling is involved (measured prototype: passband deviation 7.7e-07 dB, rejection 141.0 dB).
pub const SRC_TAPS_UNITY: usize = 110;
/// Phases of the ASRC bank; positions between phases are cubic (4-point Lagrange) interpolated.
pub const SRC_ASRC_PHASES: usize = 256;

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_crfb_coefficient_lookups() {
        assert!(get_crfb_coefficients(DsdBitRateHz::DSD64).is_some());
        assert!(get_crfb_coefficients(DsdBitRateHz::DSD128).is_some());
        assert!(get_crfb_coefficients(DsdBitRateHz::DSD256).is_some());
        assert!(get_crfb_coefficients(DsdBitRateHz::DSD512).is_some());
        assert!(get_crfb_coefficients(DsdBitRateHz::DSD64_48).is_some());
        assert!(get_crfb_coefficients(DsdBitRateHz::DSD128_48).is_some());
        assert!(get_crfb_coefficients(DsdBitRateHz::DSD256_48).is_some());
        assert!(get_crfb_coefficients(DsdBitRateHz::DSD512_48).is_some());

        let dsd256 = get_crfb_coefficients(DsdBitRateHz::DSD256).unwrap();
        assert!(dsd256.g1 > 0.0);
        assert!(dsd256.g2 > 0.0);
        assert!(dsd256.b1 > 0.0);
        assert_eq!(dsd256.a.len(), 5);
        for &a_val in &dsd256.a {
            assert!(a_val > 0.0);
        }

        let dsd512 = get_crfb_coefficients(DsdBitRateHz::DSD512).unwrap();
        assert!(dsd512.g1 > 0.0);
        assert!(dsd512.g2 > 0.0);
        assert!(dsd512.b1 > 0.0);
        assert_eq!(dsd512.a.len(), 5);
        for &a_val in &dsd512.a {
            assert!(a_val > 0.0);
        }

        assert!(get_crfb7_coefficients(DsdBitRateHz::DSD64).is_some());
        assert!(get_crfb7_coefficients(DsdBitRateHz::DSD128).is_some());
        assert!(get_crfb7_coefficients(DsdBitRateHz::DSD256).is_some());
        assert!(get_crfb7_coefficients(DsdBitRateHz::DSD512).is_some());
        assert!(get_crfb7_coefficients(DsdBitRateHz::DSD64_48).is_some());
        assert!(get_crfb7_coefficients(DsdBitRateHz::DSD128_48).is_some());
        assert!(get_crfb7_coefficients(DsdBitRateHz::DSD256_48).is_some());
        assert!(get_crfb7_coefficients(DsdBitRateHz::DSD512_48).is_some());

        let dsd256_7 = get_crfb7_coefficients(DsdBitRateHz::DSD256).unwrap();
        assert!(dsd256_7.g1 > 0.0);
        assert!(dsd256_7.g2 > 0.0);
        assert!(dsd256_7.g3 > 0.0);
        assert!(dsd256_7.b1 > 0.0);
        assert_eq!(dsd256_7.a.len(), 7);
        for &a_val in &dsd256_7.a {
            assert!(a_val > 0.0);
        }

        let dsd512_7 = get_crfb7_coefficients(DsdBitRateHz::DSD512).unwrap();
        assert!(dsd512_7.g1 > 0.0);
        assert!(dsd512_7.g2 > 0.0);
        assert!(dsd512_7.g3 > 0.0);
        assert!(dsd512_7.b1 > 0.0);
        assert_eq!(dsd512_7.a.len(), 7);
        for &a_val in &dsd512_7.a {
            assert!(a_val > 0.0);
        }
    }

    #[test]
    fn test_halfband_stage_lengths_and_dc() {
        // Full lengths 199/31/19/15/11/11/7/7/7 -> (N + 1) / 4 unique odd taps.
        let expected = [50usize, 8, 5, 4, 3, 3, 2, 2, 2];
        assert_eq!(HALFBAND_MAX_STAGES, expected.len());
        for (stage, &len) in expected.iter().enumerate() {
            let odd = get_halfband_odd_taps(stage);
            assert_eq!(odd.len(), len, "stage {stage}");
            // The 0.5 centre tap plus both mirrored odd halves give unity DC.
            assert!(
                (odd.iter().sum::<f64>() * 2.0 - 0.5).abs() < 1e-12,
                "stage {stage}"
            );
            let minimum = get_halfband_minimum_taps(stage);
            assert_eq!(minimum.len(), 4 * len - 1, "stage {stage}");
            assert!(
                (minimum.iter().sum::<f64>() - 1.0).abs() < 1e-12,
                "stage {stage}"
            );
        }
        // Stages past the table reuse the last design.
        assert_eq!(
            get_halfband_odd_taps(HALFBAND_MAX_STAGES),
            get_halfband_odd_taps(HALFBAND_MAX_STAGES - 1)
        );
    }

    fn general_taps(taps: HalfBandTaps) -> &'static [f64] {
        match taps {
            HalfBandTaps::General(taps) => taps,
            HalfBandTaps::Symmetric(_) => panic!("expected general full-length taps"),
        }
    }

    #[test]
    fn test_interpolation_filter_matrix() {
        use FilterPhase::{Linear, Minimum};

        assert!(matches!(
            get_interpolation_stage_filter(0, Linear, Apodization::Off),
            HalfBandTaps::Symmetric(_)
        ));
        assert_eq!(
            general_taps(get_interpolation_stage_filter(0, Minimum, Apodization::Off)).len(),
            199
        );

        let expected = [
            (Apodization::PassEdge18000, 209usize),
            (Apodization::PassEdge18500, 237),
            (Apodization::PassEdge19000, 277),
            (Apodization::PassEdge20000, 409),
        ];
        for (apodization, len) in expected {
            for phase in [Linear, Minimum] {
                let taps = general_taps(get_interpolation_stage_filter(0, phase, apodization));
                assert_eq!(taps.len(), len, "{apodization:?}/{phase:?}");
                assert!((taps.iter().sum::<f64>() - 1.0).abs() < 1e-12);
            }
            // Apodization only affects stage 0.
            assert_eq!(
                get_interpolation_stage_filter(1, Linear, apodization),
                get_interpolation_stage_filter(1, Linear, Apodization::Off)
            );
        }
        assert_eq!(
            get_interpolation_stage_filter(3, Linear, Apodization::Off),
            HalfBandTaps::Symmetric(&HALFBAND_STAGE3_ODD_TAPS)
        );
        assert_eq!(
            get_interpolation_stage_filter(3, Minimum, Apodization::Off),
            HalfBandTaps::General(&HALFBAND_STAGE3_MINIMUM_TAPS)
        );
    }
}
